package main

import (
	"crypto/x509"
	"encoding/hex"
	"fmt"
)

const cert = ""

// A certificate parsed 200000 times, its names and dates read each time.
func main() {
	der, _ := hex.DecodeString(cert)
	total := int64(0)
	for i := 0; i < 200000; i++ {
		c, err := x509.ParseCertificate(der)
		if err != nil {
			panic(err)
		}
		total += int64(len(c.DNSNames) + len(c.IPAddresses) + len(c.Subject.CommonName))
		total += c.NotAfter.Unix() - c.NotBefore.Unix()
	}
	fmt.Println(total)
}
